import{_ as d,o as e,c as a,a3 as r}from"./chunks/framework.CqzWVxDX.js";const b=JSON.parse('{"title":"IEC 61850 协议介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/iec61850/index.md","filePath":"guide/protocols/iec61850/index.md","lastUpdated":1786981506000}'),n={name:"guide/protocols/iec61850/index.md"};function s(l,t,o,i,h,p){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="iec-61850-协议介绍" tabindex="-1">IEC 61850 协议介绍 <a class="header-anchor" href="#iec-61850-协议介绍" aria-label="Permalink to &quot;IEC 61850 协议介绍&quot;">​</a></h1><h2 id="协议概述" tabindex="-1">协议概述 <a class="header-anchor" href="#协议概述" aria-label="Permalink to &quot;协议概述&quot;">​</a></h2><p>IEC 61850 是<strong>新一代智能变电站通信标准</strong>，定义了变电站自动化系统的信息建模、通信服务与工程配置，是智能变电站的核心标准。与传统的&quot;点表式&quot;协议不同，它采用<strong>面向对象的数据模型</strong>（IED → 逻辑设备 → 逻辑节点 → 数据对象 → 数据属性），自描述能力强。</p><p>EMS Simulate 基于 <code>pyiec61850-ng</code> 库实现，提供 <strong>MMS / GOOSE / Reports / Files / SCL / 建模工作台</strong> 完整功能链，可模拟完整的智能变电站 IED 设备，也可作为客户端连接真实 IED。</p><h2 id="子模块一览" tabindex="-1">子模块一览 <a class="header-anchor" href="#子模块一览" aria-label="Permalink to &quot;子模块一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>子模块</th><th style="text-align:center;">服务端</th><th style="text-align:center;">客户端</th><th>说明</th></tr></thead><tbody><tr><td><strong>MMS / 数据模型</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>制造报文规范：数据读写、模型浏览与导出（ICD/XML/JSON/CSV）</td></tr><tr><td><strong>GOOSE</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>通用面向对象变电站事件：发布/订阅/抓包，支持真实网卡选择</td></tr><tr><td><strong>Reports</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>BRCB / URCB 报告控制块，数据变化/品质变化/总召唤触发</td></tr><tr><td><strong>Files</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>文件目录浏览与传输</td></tr><tr><td><strong>SCL</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td>ICD/CID/SCD 文件上传、校验、对比与测点/GOOSE/Report 导入</td></tr><tr><td><strong>建模工作台</strong></td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td>基于 SCL 文件的模型工程化管理（创建/编辑/校验/发布）</td></tr><tr><td><strong>SV</strong></td><td style="text-align:center;">规划中</td><td style="text-align:center;">—</td><td>采样值发布（骨架实现）</td></tr></tbody></table><h2 id="数据模型层级" tabindex="-1">数据模型层级 <a class="header-anchor" href="#数据模型层级" aria-label="Permalink to &quot;数据模型层级&quot;">​</a></h2><p>IEC 61850 采用分层对象模型：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IED（智能电子设备）</span></span>
<span class="line"><span>└── AccessPoint（访问点）</span></span>
<span class="line"><span>    └── Server</span></span>
<span class="line"><span>        └── LDevice（逻辑设备 LD，如 LD0、PROT）</span></span>
<span class="line"><span>            └── LN（逻辑节点，如 LLN0、MMXU、XCBR、CSWI）</span></span>
<span class="line"><span>                ├── DO（数据对象，如 Mod、Pos、TotW）</span></span>
<span class="line"><span>                │   └── DA（数据属性，如 stVal、q、t、ctlModel）</span></span>
<span class="line"><span>                └── DataSet（数据集，供 GOOSE / Report 引用）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>每个数据属性带<strong>功能约束（FC）</strong>，标识数据的用途：</p><table tabindex="0"><thead><tr><th>FC</th><th>含义</th><th>典型数据</th></tr></thead><tbody><tr><td>MX</td><td>测量值</td><td>电流、电压、功率</td></tr><tr><td>ST</td><td>状态信息</td><td>开关位置、状态</td></tr><tr><td>CO</td><td>控制</td><td>分/合闸命令</td></tr><tr><td>CF</td><td>配置</td><td>定值、参数</td></tr><tr><td>DC / EX</td><td>描述 / 扩展描述</td><td>铭牌、说明</td></tr></tbody></table><h2 id="常用逻辑节点" tabindex="-1">常用逻辑节点 <a class="header-anchor" href="#常用逻辑节点" aria-label="Permalink to &quot;常用逻辑节点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>LN</th><th>名称</th><th>功能</th></tr></thead><tbody><tr><td>LLN0</td><td>零类逻辑节点</td><td>公共数据（Mod、Beh、Health），数据集定义</td></tr><tr><td>LPHD</td><td>物理设备</td><td>设备铭牌、健康状态</td></tr><tr><td>MMXU</td><td>测量</td><td>三相电压/电流/功率</td></tr><tr><td>XCBR</td><td>断路器</td><td>开关位置、分合闸控制</td></tr><tr><td>XSWI</td><td>隔离开关</td><td>位置与控制</td></tr><tr><td>CSWI</td><td>开关控制</td><td>控制接口</td></tr></tbody></table><h2 id="通信服务" tabindex="-1">通信服务 <a class="header-anchor" href="#通信服务" aria-label="Permalink to &quot;通信服务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>服务</th><th>传输</th><th>说明</th></tr></thead><tbody><tr><td>MMS</td><td>TCP 102 端口</td><td>数据读写、模型浏览、报告、文件服务</td></tr><tr><td>GOOSE</td><td>以太网二层组播</td><td>快速变位广播（&lt;4ms），无需 TCP/IP</td></tr><tr><td>SV</td><td>以太网二层</td><td>采样值（规划中）</td></tr><tr><td>MMS 报告</td><td>TCP</td><td>报告控制块上送（URCB/BRCB）</td></tr></tbody></table><h2 id="角色说明" tabindex="-1">角色说明 <a class="header-anchor" href="#角色说明" aria-label="Permalink to &quot;角色说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>行为</th></tr></thead><tbody><tr><td><strong>服务端（Server）</strong></td><td>导入 ICD/SCD/CID 模型后模拟 IED：响应 MMS 读写、按报告控制块上送报告、发布/接收 GOOSE、提供文件服务</td></tr><tr><td><strong>客户端（Client）</strong></td><td>连接真实 IED：动态发现数据模型、读写数据、订阅 GOOSE 与报告、浏览文件</td></tr></tbody></table><h2 id="常用术语" tabindex="-1">常用术语 <a class="header-anchor" href="#常用术语" aria-label="Permalink to &quot;常用术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td>SCL</td><td>变电站配置描述语言（ICD/CID/SCD 文件）</td></tr><tr><td>ICD</td><td>IED 能力描述文件（单 IED）</td></tr><tr><td>SCD</td><td>全站系统配置文件</td></tr><tr><td>FCDA</td><td>功能约束数据属性（DataSet 成员引用）</td></tr><tr><td>RCB</td><td>报告控制块（URCB 非缓存 / BRCB 缓存）</td></tr><tr><td>GCB</td><td>GOOSE 控制块</td></tr></tbody></table><blockquote><p>📄 详细操作见 <a href="./operation.html">IEC 61850 操作指南</a>，报文解析见 <a href="./packet-view.html">IEC 61850 报文查看</a>。</p></blockquote>`,20)])])}const g=d(n,[["render",s]]);export{b as __pageData,g as default};
